using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class BinaryCenterReflectionDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The entire original singleton sphere reflects into a pure affine sphere, with two geometric alternatives.",
        H("Reflected original pure spheres"), Blocks(
        Paragraph(Text("V is the original finite dimensional real normed carrier, C its entire closed pointed generating cone and u its strictly positive unit. K is the entire normalized base and P its full extreme-point locus. All original proper effects remain available. B denotes whole original exclusion balls and BC compares every original binary mixture equality with independent closed-unit-interval weights, including repeated endpoints and zero weights. Centers are ContinuousFrameSum.center. For an entire chart b of the singleton-label F=D(p), the actual BC center graph g gives k(x)=2g(x)-p; A is the entire closed-ball image of k and its center is k(0)=2g(0)-p. All relative topology uses the indicated affine spans.")),
        Describe.Lean(DescribeId.Create("reflected-center-ball"),DeclarationHandle.Create("D5/S3/Quantum/Foundation/BinaryCenterReflection.reflected_center_ball"),
            H("The entire reflected pure sphere and equality criterion"),StatementSource.WithoutFormula(),AssessedProvenance.FromRepo(),Blocks(
                Paragraph(Text("For every same original domain, B and complete original BC, every original pure p with SingleLabel(C,u,p), and every whole ExclusionChart b of D(p), there exist affine maps g and k on the Euclidean chart carrier. For every source unit x, g(x) is the actual center of D(q), where q=b(x) is the original pure chart point, and k(x)=2g(x)-p for every source x. The map k is injective, its linear range has dimension b.dim, its entire closed unit ball image lies in K and its entire unit sphere image lies in P. Moreover that entire ball image equals D(p) if and only if for every source unit x, g(x)=(p+2center(D(p))-b(x))/2.")),
                Paragraph(Text("Original zero symmetry puts p in D(q). The exact original sphere identity expresses p as a unit chart point of that whole D(q); its antipodal point is a pure r with r=2center(D(q))-p. This proves purity on the entire reflected sphere. Convex generation gives all of A inside K. If A=F, then q and r lie on the same whole F and the same original zero-one effect witnesses their exclusion relation. The original orthogonal_center_sum owner forces q+r=2center(F), yielding the stated formula. Conversely that formula identifies k(x) with the opposite original sphere point b(-x), so sphere convex generation identifies the entire balls."))),DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("original-reflected-alternatives"),DeclarationHandle.Create("D5/S3/Quantum/Foundation/BinaryCenterReflection.original_reflected_alternatives"),
            H("The original three-ball alternatives"),StatementSource.WithoutFormula(),AssessedProvenance.FromRepo(),Blocks(
                Paragraph(Text("Assume additionally the original nonzero carrier and EB3. For every original singleton-label p there are a whole three-dimensional chart b and maps g,k with the preceding original boundary-center and reflection identities. The reflected map is injective of rank three; A lies in the original K; its intrinsic frontier is exactly its entire reflected unit sphere and is pure. Every y in A has 2k(0)-y in A, so k(0) is its affine center. Exactly one geometric alternative applies: when that center lies on the original intrinsic frontier of K, A equals an entire original exclusion D(r) for some original pure r; when it lies in the intrinsic interior of K, A equals K intersect its own affine span and is not an extreme face of K. The same original A=F boundary-center formula equivalence is included.")),
                Paragraph(Text("At a boundary center, original frontier coverage and its original exposing effect give a nonnegative affine functional on the entire reflected ball that vanishes at an interior source point. It vanishes everywhere, placing A inside one whole original exclusion. Both have dimension three, and the entire smaller sphere is extreme in K, so affine-ball rigidity gives equality. At an interior center, a point beyond A in the same affine carrier would place a pure sphere point on an interior segment in K, a contradiction. The original dimension-at-least-six result makes A proper; original face classification and its interior center then exclude faciality."))),DescribeRole.Theorem),
        Paragraph(Text("The boundary alternative permits a different original ball; the interior alternative is retained. Neither implies A=F. No BC to MC, global label injectivity, closed pure locus, uniform diameter bound, common vector p+2center(D(p)), two-outside crossing exclusion, quantum classification or physical realization is asserted.")))));
}
